def convert_sample_values(samples, src_bps, src_float, dst_bps, dst_float):
    """Convert a list of samples between integer/float representations."""
    if src_float and dst_float:
        return [float(v) for v in samples]
    if src_float and not dst_float:
        maxv = (1 << (dst_bps - 1)) - 1
        minv = -(1 << (dst_bps - 1))
        scale = float(1 << (dst_bps - 1))
        out = []
        for v in samples:
            iv = int(round(float(v) * scale))
            out.append(clamp(iv, minv, maxv))
        return out
    if not src_float and dst_float:
        scale = float(1 << (src_bps - 1))
        return [float(v) / scale for v in samples]
    # int -> int
    if dst_bps == src_bps:
        return list(samples)
    if dst_bps > src_bps:
        shift = dst_bps - src_bps
        return [int(v) << shift for v in samples]
    shift = src_bps - dst_bps
    return [int(v) >> shift for v in samples]

