            if audio.is_float:
                flac_bps = 24 if audio.fmt == 'flt' else 32
            elif audio.bps <= 16:
                flac_bps = 16
            elif audio.bps <= 24:
                flac_bps = 24
            else:
                flac_bps = 32
        samples = convert_sample_values(audio.samples, audio.bps, audio.is_float, flac_bps, False)
        fmt = 's16' if flac_bps <= 16 else 's32'
        return samples, flac_bps, fmt, False
    info = PCM_INFO.get(target_codec)
    if info is None:
        return list(audio.samples), audio.bps, audio.fmt, audio.is_float
    kind, bits, endian, dfmt, bps = info
