def _alaw_encode_sample(v):
    # from the classic G.711 A-law algorithm
    mask = 0xD5
    sign = 0x80 if v >= 0 else 0
    if v < 0: v = -v
    if v > 32635: v = 32635
    if v >= 256:
        exp = 1
        temp = v >> 8
        while temp > 1:
            temp >>= 1; exp += 1
        mant = (v >> (exp + 3)) & 0x0f
        code = sign | (exp << 4) | mant
    else:
        code = sign | ((v >> 4) & 0x0f)
    return code ^ mask

def _alaw_decode_sample(code):
    code ^= 0x55
    sign = code & 0x80
    exp = (code >> 4) & 0x07
    data = code & 0x0f
    if exp == 0:
        v = (data << 4) + 8
    else:
        v = ((data << 4) + 0x108) << (exp - 1) if exp > 1 else ((data << 4) + 0x108)
        # the branch above mirrors the table formula below for clarity
        v = ((data << 4) + 0x108)
        if exp > 1:
            v <<= (exp - 1)
    return -v if not sign else v

_ALAW_DECODE_TABLE = None
_MULAW_DECODE_TABLE = None
def _build_g711():
    global _ALAW_DECODE_TABLE, _MULAW_DECODE_TABLE
    if _ALAW_DECODE_TABLE is not None:
        return
    _ALAW_DECODE_TABLE = [_alaw_decode_sample(i) for i in range(256)]
    # mu-law decode (classic formula)
    tbl = []
    for code in range(256):
        c = ~code & 0xff
        sign = c & 0x80
        exp = (c >> 4) & 0x07
        mant = c & 0x0f
        v = ((mant << 3) + 0x84) << exp
        v -= 0x84
        tbl.append(-v if sign else v)
    _MULAW_DECODE_TABLE = tbl

def _mulaw_encode_sample(v):
    _build_g711()
    # binary-search style classic encoder
    sign = 0x80 if v < 0 else 0
    if v < 0: v = -v
    if v > 32635: v = 32635
    v += 0x84
    exp = 7
    mask = 0x4000
    while exp > 0 and not (v & mask):
        exp -= 1; mask >>= 1
    mant = (v >> (exp + 3)) & 0x0f
    return (~(sign | (exp << 4) | mant)) & 0xff

def encode_pcm_bytes(samples, codec, bps=None, is_float=False):
    info = PCM_INFO.get(codec)
    if info is None:
        # fallback s16le
        info = PCM_INFO['pcm_s16le']; codec = 'pcm_s16le'
    kind, bits, endian, dfmt, cbps = info
    _build_g711()
    if kind == 'alaw':
        return bytes(_alaw_encode_sample(clamp(int(v), -32768, 32767)) for v in samples)
    if kind == 'mulaw':
        return bytes(_mulaw_encode_sample(clamp(int(v), -32768, 32767)) for v in samples)
    if kind == 'f':
        fmtch = ('<%df' if endian == 'le' else '>%df') if bits == 32 else ('<%dd' if endian == 'le' else '>%dd')
        return struct.pack(fmtch % len(samples), *samples) if samples else b''
    # integers: encode signed internal representation
    out = bytearray()
    nbytes = bits // 8
    bias = (1 << (bits - 1)) if kind == 'u' else 0
    if bits == 8:
        if kind == 'u':
            return bytes(clamp(int(v) + 128, 0, 255) for v in samples)
        return bytes(clamp(int(v), -128, 127) & 0xff for v in samples)
    if bits == 16 and endian == 'le' and kind == 's':
        return struct.pack('<%dh' % len(samples), *[clamp(int(v), -32768, 32767) for v in samples]) if samples else b''
    if bits == 16 and endian == 'be' and kind == 's':
        return struct.pack('>%dh' % len(samples), *[clamp(int(v), -32768, 32767) for v in samples]) if samples else b''
    if bits == 32 and endian == 'le' and kind == 's':
        return struct.pack('<%di' % len(samples), *[clamp(int(v), -2147483648, 2147483647) for v in samples]) if samples else b''
    if bits == 32 and endian == 'be' and kind == 's':
        return struct.pack('>%di' % len(samples), *[clamp(int(v), -2147483648, 2147483647) for v in samples]) if samples else b''
    if bits == 64 and kind == 's':
        fmtch = '<%dq' if endian == 'le' else '>%dq'
        return struct.pack(fmtch % len(samples), *samples) if samples else b''
    # generic path (24-bit / unsigned)
    for v in samples:
        iv = int(v) + bias
        iv &= (1 << bits) - 1
        b = iv.to_bytes(nbytes, 'little' if endian == 'le' else 'big', signed=False)
        out += b
