def decode_pcm_bytes(data, codec, count=None):
    info = PCM_INFO.get(codec)
    if info is None:
        info = PCM_INFO['pcm_s16le']; codec = 'pcm_s16le'
    kind, bits, endian, dfmt, cbps = info
    _build_g711()
    if kind == 'alaw':
        return [_ALAW_DECODE_TABLE[b] for b in data], 16, 's16', False
    if kind == 'mulaw':
        return [_MULAW_DECODE_TABLE[b] for b in data], 16, 's16', False
    nbytes = bits // 8
    n = len(data) // nbytes
    if count is not None:
        n = min(n, count)
    if kind == 'f':
        fmtch = ('<%df' if endian == 'le' else '>%df') if bits == 32 else ('<%dd' if endian == 'le' else '>%dd')
        vals = list(struct.unpack(fmtch % n, data[:n * nbytes])) if n else []
        return vals, bits, dfmt, True
    if bits == 8:
        if kind == 'u':
            return [b - 128 for b in data[:n]], 8, dfmt, False
        return [b - 256 if b > 127 else b for b in data[:n]], 8, dfmt, False
    if bits == 16 and kind == 's':
        fmtch = '<%dh' if endian == 'le' else '>%dh'
        return list(struct.unpack(fmtch % n, data[:n * 2])) if n else [], 16, dfmt, False
    if bits == 32 and kind == 's':
        fmtch = '<%di' if endian == 'le' else '>%di'
        return list(struct.unpack(fmtch % n, data[:n * 4])) if n else [], 32, dfmt, False
    if bits == 64 and kind == 's':
        fmtch = '<%dq' if endian == 'le' else '>%dq'
        return list(struct.unpack(fmtch % n, data[:n * 8])) if n else [], 64, dfmt, False
    # generic
    bias = (1 << (bits - 1)) if kind == 'u' else 0
    out = []
    for i in range(n):
        chunk = data[i * nbytes:(i + 1) * nbytes]
        iv = int.from_bytes(chunk, 'little' if endian == 'le' else 'big', signed=False)
        if kind == 'u':
            out.append(iv - bias)
        else:
            if iv >= (1 << (bits - 1)):
                iv -= (1 << bits)
            out.append(iv)
    return out, cbps, dfmt, False

