def format_duration_hms(seconds):
    if seconds is None or seconds < 0:
        seconds = 0
    total_cs = int(seconds * 100 + 1e-9)
    cs = total_cs % 100
    total_s = total_cs // 100
    s = total_s % 60
    m = (total_s // 60) % 60
    h = total_s // 3600
    return "%02d:%02d:%02d.%02d" % (h, m, s, cs)

def format_elapsed(seconds):
