    cs = total_cs % 100
    total_s = total_cs // 100
    s = total_s % 60
    m = (total_s // 60) % 60
    h = total_s // 3600
    return "%d:%02d:%02d.%02d" % (h, m, s, cs)

def parse_time_value(s, default=None):
    """Parse an ffmpeg-style duration/time string to seconds (float)."""
    if s is None:
        return default
    if isinstance(s, (int, float)):
        return float(s)
    txt = str(s).strip()
    if txt == '':
        raise ValueError("empty time")
    sign = 1.0
    if txt.startswith('-'):
        sign = -1.0; txt = txt[1:]
    elif txt.startswith('+'):
        txt = txt[1:]
    try:
        if ':' in txt:
            parts = txt.split(':')
            if len(parts) > 3:
                raise ValueError(txt)
            vals = [float(p) for p in parts]
            sec = 0.0
            for v in vals:
                sec = sec * 60.0 + v
            return sign * sec
        # suffixes
        mult = 1.0
        low = txt.lower()
        if low.endswith('us'):
            mult = 1e-6; txt = txt[:-2]
        elif low.endswith('ms'):
            mult = 1e-3; txt = txt[:-2]
        elif low.endswith('min'):
            mult = 60.0; txt = txt[:-3]
        elif low.endswith('s'):
            mult = 1.0; txt = txt[:-1]
        elif low.endswith('m'):
            mult = 60.0; txt = txt[:-1]
        elif low.endswith('h'):
            mult = 3600.0; txt = txt[:-1]
        return sign * float(txt) * mult
    except ValueError:
        raise ValueError("Invalid duration: %r" % s)

def parse_int_value(s):
    txt = str(s).strip().lower()
    mult = 1
    if txt.endswith('k'):
        mult = 1000; txt = txt[:-1]
    elif txt.endswith('m'):
        mult = 1000000; txt = txt[:-1]
    return int(float(txt) * mult)

def parse_rate_value(s):
    txt = str(s).strip()
    if '/' in txt:
        a, b = txt.split('/', 1)
        return int(float(a) / float(b))
    return parse_int_value(txt)

