        return 10 ** (float(txt[:-2]) / 20.0)
    if txt.endswith('%'):
        return float(txt[:-1]) / 100.0
    # allow simple arithmetic with python eval on numbers
    if re.fullmatch(r'[0-9eE\+\-\*/\.\(\) ]+', txt):
        return float(eval(txt, {'__builtins__': {}}, {}))
    raise ValueError(txt)

def apply_biquad(audio, freq, kind):
    if audio.rate <= 0 or audio.frames() == 0:
        return
    # RBJ biquad, Q=0.707
    w0 = 2 * math.pi * freq / audio.rate
    alpha = math.sin(w0) / (2 * 0.70710678)
    cw = math.cos(w0)
    if kind == 'lowpass':
        b0 = (1 - cw) / 2; b1 = 1 - cw; b2 = (1 - cw) / 2; a0 = 1 + alpha; a1 = -2 * cw; a2 = 1 - alpha
    else:
        b0 = (1 + cw) / 2; b1 = -(1 + cw); b2 = (1 + cw) / 2; a0 = 1 + alpha; a1 = -2 * cw; a2 = 1 - alpha
    b0/=a0; b1/=a0; b2/=a0; a1/=a0; a2/=a0
    chans = audio.deinterleave()
    out_chans = []
    for data in chans:
        out = []; x1=x2=y1=y2=0.0
        for v in data:
            x = float(v); y = b0*x + b1*x1 + b2*x2 - a1*y1 - a2*y2
            x2=x1; x1=x; y2=y1; y1=y
            out.append(y)
        if not audio.is_float:
            lo=-(1<<(audio.bps-1)); hi=(1<<(audio.bps-1))-1
            out=[clamp(int(round(v)),lo,hi) for v in out]
        out_chans.append(out)
    audio.set_channels_data(out_chans)

def apply_atempo(audio, tempo):
    # crude time-scale using linear interpolation at playback rate = tempo
    # (duration divided by tempo, pitch also changes - acceptable fallback)
    in_frames = audio.frames()
    if in_frames == 0: return
    out_frames = int(round(in_frames / tempo))
    chans = audio.deinterleave(); out_chans=[]
    for data in chans:
        out=[]
        for i in range(out_frames):
            pos = i * tempo; j=int(math.floor(pos)); f=pos-j
            if j >= len(data)-1: out.append(data[-1])
            else: out.append(float(data[j])*(1-f)+float(data[j+1])*f)
        if not audio.is_float:
            lo=-(1<<(audio.bps-1)); hi=(1<<(audio.bps-1))-1
            out=[clamp(int(round(v)),lo,hi) for v in out]
        out_chans.append(out)
    audio.set_channels_data(out_chans)

def apply_pan(audio, argstr):
    if not argstr: return
    # e.g. stereo|c0=c0|c1=c0  or mono|c0=c0+c1
    if '|' not in argstr: return
    parts = argstr.split('|')
    layout_part = parts[0].strip()
    if layout_part in LAYOUT_COUNTS:
        new_ch = LAYOUT_COUNTS[layout_part]
    elif layout_part.isdigit():
        new_ch = int(layout_part)
    else:
        new_ch = len(parts)-1
    chans = audio.deinterleave()
    n = audio.frames()
    out_chans = []
    for expr in parts[1:1+new_ch]:
        # expr like c0=c0+0.5*c1 or just c0
        rhs = expr.split('=',1)[1] if '=' in expr else expr
        out = [0.0]*n
        # terms separated by +/-
        for term in re.findall(r'[+-]?[^+-]+', rhs):
            term=term.strip()
            if not term: continue
            sign=1.0
            if term.startswith('+'): term=term[1:]
            elif term.startswith('-'): sign=-1.0; term=term[1:]
            m=re.fullmatch(r'([0-9\.eE]+)\*?c(\d+)', term)
            m2=re.fullmatch(r'c(\d+)(?:\*([0-9\.eE]+))?', term)
            if m:
                coef=float(m.group(1)); ci=int(m.group(2))
            elif m2:
                ci=int(m2.group(1)); coef=float(m2.group(2)) if m2.group(2) else 1.0
            else:
                continue
            if ci < len(chans):
                src=chans[ci]
                for i in range(n): out[i]+=sign*coef*float(src[i])
        if not audio.is_float:
            lo=-(1<<(audio.bps-1)); hi=(1<<(audio.bps-1))-1
            out=[clamp(int(round(v)),lo,hi) for v in out]
        out_chans.append(out)
    if out_chans:
        audio.set_channels_data(out_chans)

_filter_names_cache=None
def get_filter_names():
    global _filter_names_cache
    if _filter_names_cache is not None:
        return _filter_names_cache
    names=set(['volume','atrim','aresample','aformat','pan','sine','anullsrc','aevalsrc','loudnorm','lowpass','highpass','afade','adelay','acopy','anull','asetpts','asetrate','areverse','apad','atempo','trim'])
    try:
        txt=load_data().get('filters','')
        for line in txt.splitlines():
            m=re.match(r'\s*\S+\s+(\S+)\s', line)
            if m: names.add(m.group(1))
    except Exception: pass
    _filter_names_cache=names
    return names

