    except FileNotFoundError:
        raise FFError('enoent', path)
    except IsADirectoryError:
        raise FFError('isdir', path)
    except PermissionError:
        raise FFError('eacces', path)
    except OSError as e:
        raise FFError('enoent', path)

# ------------------------------------------------------------- option store
class Opts:
    def __init__(self):
        self.items=[]  # list of (key, value) key includes :spec if any
    def add(self, key, value):
        self.items.append((key, value))
    def get_all(self, names):
        return [v for k,v in self.items if k in names]
    def get(self, names, default=None):
        vals=self.get_all(names)
        return vals[-1] if vals else default
    def has(self, names):
        return any(k in names for k,v in self.items)

def get_opt(opts, names, default=None):
    if opts is None: return default
    if isinstance(opts, Opts):
        return opts.get(names, default)
    return default
def get_opts_all(opts, names):
    if isinstance(opts, Opts):
        return opts.get_all(names)
    return []

