                        # consume rest of line if present and stdin is not a tty? ffmpeg reads a line-ish; reading 1 byte leaves newline for possible next prompt - to mimic, consume until newline if available and data is pipe
                        # do not block: only if stdin is not tty, try to drain line in non? skip
                    except Exception:
