        contexts.append(ctx)
    # stream mapping
    ST.info("Stream mapping:\n")
    for ctx in contexts:
        src=ctx.source_orig
        if ctx.copy_mode:
            ST.info("  Stream #%d:0 -> #%d:0 (copy)\n" % (ctx.source_index, ctx.index))
        else:
            ST.info("  Stream #%d:0 -> #%d:0 (%s (native) -> %s (native))\n" % (ctx.source_index, ctx.index, src.codec, ctx.codec))
    if not ST.nostdin:
        ST.info("Press [q] to stop, [?] for help\n")
    ST.start_time=time.time()
    stats_list=[]
