                ST.error("[AVFilterGraph @ %s] Error initializing filters\n" % ST.addr())
                eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % ctx.url); return 234
            if e.kind=='invalidarg_atrim_start':
                ST.print_banner()
                ST.error("[Parsed_atrim_0 @ %s] Unable to parse \"start\" option value \"%s\" as duration\n" % (ST.addr(), e.msg))
                ST.error("[fc#-1 @ %s] Error applying option 'start' to filter 'atrim': Invalid argument\n" % ST.addr())
                eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % ctx.url); return 234
