            overhead=(stats['total']-stats['audio'])/float(stats['audio'])*100.0
            overhead_str="%.6f%%" % overhead
        elif ctx.fmt in ('null','md5','hash','streamhash'):
            overhead_str='unknown'
        elif stats['audio']==0:
            overhead_str='unknown'
        audio_kib=int(round(stats['audio']/1024.0))
        ST.info("[out#%d/%s @ %s] video:0KiB audio:%dKiB subtitle:0KiB other streams:0KiB global headers:0KiB muxing overhead: %s\n" % (ctx.index, ctx.fmt, ctx.out_addr, audio_kib, overhead_str))
    if stats_list:
        ctx, stats = stats_list[0]
        elapsed=max(time.time()-ST.start_time, 0.001)
        dur=stats['duration']
        if ctx.fmt=='null':
            size_str='size=N/A'
            bitrate_str='bitrate=N/A'
            speed_str=''
            # build like ffmpeg: size=N/A time=... bitrate=N/A speed=...x
            if dur>0:
                spd=dur/elapsed; spd_s=("%.3g" % spd)+'x'
                ST.info("size=N/A time=%s bitrate=N/A speed=%5s elapsed=%s    \n" % (format_duration_hms(dur), spd_s, format_elapsed(elapsed)))
            else:
                ST.info("size=N/A time=%s bitrate=N/A speed=N/A elapsed=%s    \n" % (format_duration_hms(dur), format_elapsed(elapsed)))
        else:
            total=stats['total']; kib=int(round(total/1024.0))
            size_field="%dKiB" % kib
            if dur>0:
                br=total*8/dur/1000.0
                spd=dur/elapsed; spd_s=("%.3g" % spd)+'x'
                ST.info("size=%11s time=%s bitrate=%6.1fkbits/s speed=%5s elapsed=%s    \n" % (size_field, format_duration_hms(dur), br, spd_s, format_elapsed(elapsed)))
            else:
                ST.info("size=%11s time=%s bitrate=N/A speed=N/A elapsed=%s    \n" % (size_field, format_duration_hms(0), format_elapsed(elapsed)))
    return 0

def _print_output_header(ctx):
    ST.info("Output #%d, %s, to '%s':\n" % (ctx.index, ctx.fmt, display_url(ctx.url)))
    tmeta=transformed_metadata(ctx.output_metadata, ctx.fmt) if hasattr(ctx,'output_metadata') else {}
    if tmeta:
        ST.info("  Metadata:\n")
        for k,v in tmeta.items():
            padded=str(k).ljust(16) if len(str(k))<16 else str(k)
            ST.info("    %s: %s\n" % (padded, v))
    disp=getattr(ctx,'display_audio', None)
    # If encoding failed before display computed (flac_header), display may not exist; compute fallback
    if disp is None:
        disp=ctx.source_orig
        desc=stream_description(disp, ctx.codec, is_output=True, fmt=ctx.fmt, copy_mode=ctx.copy_mode)
    else:
        desc=stream_description(disp, ctx.codec if not ctx.copy_mode else disp.codec, is_output=True, fmt=ctx.fmt, copy_mode=ctx.copy_mode)
    ST.info("  Stream #%d:0: Audio: %s\n" % (ctx.index, desc))
    if not ctx.copy_mode:
        ST.info("    Metadata:\n")
        padded='encoder'.ljust(16)
        ST.info("      %s: %s %s\n" % (padded, LAVC_VERSION, ctx.codec))

