        sys.stdout.write(data.get('h_full','')); return 0
    if '=' in arg:
        typ, name = arg.split('=',1)
        topics = data.get('topics',{})
        if arg in topics:
            sys.stdout.write(topics[arg]); return 0
        if typ in ('decoder','encoder'):
