def do_help(arg):
    data=load_data()
    if arg is None or arg=='':
        sys.stdout.write(data.get('h','')); return 0
    if arg=='long':
        sys.stdout.write(data.get('h_long','')); return 0
    if arg=='full':
        sys.stdout.write(data.get('h_full','')); return 0
    if '=' in arg:
        typ, name = arg.split('=',1)
        topics = data.get('topics',{})
        if arg in topics:
            sys.stdout.write(topics[arg]); return 0
        if typ in ('decoder','encoder'):
            names = get_decoder_names() if typ=='decoder' else get_encoder_names()
            if name not in names:
                sys.stdout.write("Codec '%s' is not recognized by FFmpeg.\n\nExiting with exit code 0\n" % name); return 0
            # fallback generic (rare)
            label='Decoder' if typ=='decoder' else 'Encoder'
            sys.stdout.write("%s %s:\n\nExiting with exit code 0\n" % (label, name)); return 0
        if typ in ('muxer','demuxer'):
            names=get_muxer_names()|get_demuxer_names()
            if name not in names:
                sys.stdout.write("Unknown format '%s'.\n\nExiting with exit code 0\n" % name); return 0
            label='Muxer' if typ=='muxer' else 'Demuxer'
            sys.stdout.write("%s %s:\n\nExiting with exit code 0\n" % (label, name)); return 0
        if typ=='filter':
            if name not in get_filter_names():
                sys.stdout.write("Unknown filter '%s'.\n\nExiting with exit code 0\n" % name); return 0
            sys.stdout.write("Filter %s\n\nExiting with exit code 0\n" % name); return 0
        if typ=='bsf':
            sys.stdout.write("Unknown bit stream filter '%s'.\n\nExiting with exit code 0\n" % name); return 0
        if typ=='protocol':
            sys.stdout.write("Unknown protocol '%s'.\n\nExiting with exit code 0\n" % name); return 0
        # unknown help type
        sys.stdout.write("Unknown help option '%s'.\n" % typ)
        sys.stdout.write(data.get('h','')); return 0
    # unknown topic word
    sys.stdout.write("Unknown help option '%s'.\n" % arg)
    sys.stdout.write(data.get('h','')); return 0

def set_loglevel(v):
    if v is None: return
    txt=str(v).split('+')[0].split(',')[0]
    if txt in LOG_LEVELS:
        ST.loglevel=LOG_LEVELS[txt]
    else:
        try: ST.loglevel=int(txt)
        except Exception: pass

