DERIVED_CACHE=None
def get_derived_options():
    global DERIVED_CACHE
    if DERIVED_CACHE is not None: return DERIVED_CACHE
    derived={}
    try:
        for key in ('h_long','h_full'):
            txt=load_data().get(key,'')
            for line in txt.splitlines():
                m=re.match(r'\s+-([A-Za-z0-9_][A-Za-z0-9_\-]*)(?::[^\s]*)?\s+(<[^>]*>)?', line)
                if m:
                    name=m.group(1); arg=m.group(2)
                    if name not in derived:
                        derived[name]=(arg or '')
    except Exception: pass
    DERIVED_CACHE=derived
    return derived

def missing_arg_error(optname):
    ST.print_banner()
    eprint_msg("Missing argument for option '%s'.\nError splitting the argument list: Invalid argument\n" % optname)
    return 234
def unrecognized_error(rawname):
    ST.print_banner()
    eprint_msg("Unrecognized option '%s'.\nError splitting the argument list: Option not found\n" % rawname)
    return 8

BOOL_TOKENS={'0','1','true','false','yes','no','on','off'}

class FileSpec:
    def __init__(self, url, opts, is_input):
        self.url=url; self.opts=opts; self.is_input=is_input

def main(argv):
    ST.start_time=time.time()
    # ---- parsing ----
    inputs=[]; outputs=[]
    pending=Opts()
    after_dashdash=False
    i=0
    while i < len(argv):
        tok=argv[i]
        if after_dashdash:
            outputs.append(FileSpec(tok, pending, False)); pending=Opts(); i+=1; continue
        if tok=='--':
            after_dashdash=True; i+=1; continue
        if tok=='-' or not tok.startswith('-'):
            outputs.append(FileSpec(tok, pending, False)); pending=Opts(); i+=1; continue
        raw = tok[1:]
        # base / spec split
        if ':' in raw:
            base, rest = raw.split(':',1)
            spec = ':'+rest
        else:
            base, spec = raw, ''
        # -i
        if base=='i' and spec=='':
            if i+1>=len(argv):
                return missing_arg_error('i')
            url=argv[i+1]
            inputs.append(FileSpec(url, pending, True)); pending=Opts(); i+=2; continue
        # info options
        if base in ('version','L','license','muxers','demuxers','devices','decoders','encoders','filters',
                    'pix_fmts','layouts','sample_fmts','buildconf','formats','codecs','bsfs','protocols',
                    'dispositions','colors','hwaccels') and spec=='':
            return do_info(base, None, argv[i+1:])
        if base in ('h','?','help','-help') and spec=='':
            arg=None
            if i+1<len(argv):
                arg=argv[i+1]
            return do_info('h', arg, argv[i+1:])
        if base in ('sources','sinks') and spec=='':
            arg=None
            if i+1<len(argv) and not argv[i+1].startswith('-'):
                arg=argv[i+1]
            elif i+1<len(argv):
                # ffmpeg will treat next token as arg regardless? keep None for option-like
                arg=None
            return do_info(base, arg, argv[i+1:])
        # global flags / values
        if base in GLOBAL_FLAG_OPTS and spec=='':
            if base=='y': ST.overwrite=True
            elif base=='n': ST.overwrite=False
            elif base=='hide_banner': ST.hide_banner=True
            elif base=='nostdin': ST.nostdin=True
            elif base=='stdin': ST.nostdin=False
            elif base=='stats': ST.stats=True
            elif base=='nostats': ST.stats=False
            i+=1; continue
        if base in GLOBAL_VALUE_OPTS and spec=='':
            if i+1>=len(argv): return missing_arg_error(base)
            val=argv[i+1]
            if base in ('v','loglevel'): set_loglevel(val)
            i+=2; continue
        # negated booleans e.g. -nostats already, -noautorotate etc
        # perfile value / flag (base matched ignoring spec)
        if base in PERFILE_VALUE_OPTS or (base in ('c','codec') ):
            if i+1>=len(argv): return missing_arg_error(base)
            pending.add(base+spec, argv[i+1]); i+=2; continue
        if base in PERFILE_FLAG_OPTS:
            pending.add(base+spec, '1'); i+=1; continue
        if base.startswith('no') and len(base)>2:
            # -no<flag> forms
            pending.add(base+spec, '1'); i+=1; continue
        # derived options from help text
        derived=get_derived_options()
        if base in derived:
            argtype=derived[base] or ''
            if 'boolean' in argtype:
                # optional boolean value
                if i+1<len(argv) and argv[i+1] in BOOL_TOKENS:
                    pending.add(base+spec, argv[i+1]); i+=2
                else:
                    pending.add(base+spec, '1'); i+=1
                continue
            if argtype:
                if i+1>=len(argv): return missing_arg_error(base)
                pending.add(base+spec, argv[i+1]); i+=2; continue
            else:
                pending.add(base+spec, '1'); i+=1; continue
        return unrecognized_error(raw)
    # ---- end parse: print banner deferred ----
    if not inputs and not outputs:
        ST.print_banner()
        ST.log(32, "Universal media converter\nusage: ffmpeg [options] [[infile options] -i infile]... {[outfile options] outfile}...\n\nUse -h to get full help or, even better, run 'man ffmpeg'\n")
        return 1
    return run_conversion(inputs, outputs)

def _errno_exit(e):
    return (-e) % 256 if e else 1

def format_for_output(url, opts):
    fmt=get_opt(opts, ['f'])
    if fmt: return fmt, True
    if url in ('-','pipe:','pipe:1','pipe:2'):
        return None, False
    name=url
    # strip protocol/path for extension
    base=os.path.basename(name.split('?')[0])
    if '.' in base:
        ext=base.rsplit('.',1)[1].lower()
        return EXT_TO_FORMAT.get(ext), False
    return None, False

def run_conversion(inputs, outputs):
    # open inputs
    audios=[]; work_audios=[]
    # hint duration for lavfi: look for any t/to in inputs/outputs
    hint=0
    for spec in inputs+outputs:
        tv=get_opt(spec.opts, ['t'])
        if tv:
            try: hint=max(hint, parse_time_value(tv))
            except Exception: pass
    for idx, spec in enumerate(inputs):
        url=spec.url; opts=spec.opts
        # decoder forced validation
        dec=get_opt(opts, ['c','codec','c:a','acodec','codec:a'])
        if dec and dec not in ('copy',) and dec not in get_decoder_names():
            ST.print_banner(); eprint_msg("Unknown decoder '%s'\nError opening input file %s.\nError opening input files: Decoder not found\n" % (dec, url)); return 8
        # forced format validation
        fforce=get_opt(opts, ['f'])
        if fforce and fforce not in get_demuxer_names() and fforce not in RAW_FORMAT_TO_CODEC and fforce!='lavfi':
            ST.print_banner()
            ST.error("[in#%d @ %s] Unknown input format: '%s'\n" % (idx, ST.addr(), fforce))
            eprint_msg("Error opening input file %s.\nError opening input files: Invalid argument\n" % url)
            return 234
        try:
            audio=load_input_data(url, opts, hint_duration=hint)
        except FFError as e:
            ST.print_banner()
            if e.kind=='enoent':
                ST.error("[in#%d @ %s] Error opening input: No such file or directory\n" % (idx, ST.addr()))
                eprint_msg("Error opening input file %s.\nError opening input files: No such file or directory\n" % url); return 254
            if e.kind=='isdir':
                ST.error("[in#%d @ %s] Error opening input: Is a directory\n" % (idx, ST.addr()))
                eprint_msg("Error opening input file %s.\nError opening input files: Is a directory\n" % url); return 235
            if e.kind=='eacces':
                ST.error("[in#%d @ %s] Error opening input: Permission denied\n" % (idx, ST.addr()))
                eprint_msg("Error opening input file %s.\nError opening input files: Permission denied\n" % url); return 243
            # invalid data
            ST.error("[in#%d @ %s] Error opening input: Invalid data found when processing input\n" % (idx, ST.addr()))
            eprint_msg("Error opening input file %s.\nError opening input files: Invalid data found when processing input\n" % url); return 183
        except Exception as e:
            ST.print_banner()
            ST.error("[in#%d @ %s] Error opening input: Invalid data found when processing input\n" % (idx, ST.addr()))
            eprint_msg("Error opening input file %s.\nError opening input files: Invalid data found when processing input\n" % url); return 183
        audios.append(audio)
        print_input_info(audio, idx, display_url(url) if audio.format_name=='lavfi' or url not in ('-','pipe:','pipe:0') else 'pipe:')
        # working copy with input options applied
        work=audio.clone()
        ss_i=get_opt(opts, ['ss']); t_i=get_opt(opts, ['t']); to_i=get_opt(opts, ['to'])
        if ss_i is not None or t_i is not None or to_i is not None:
            try: trim_audio(work, ss=ss_i, t=t_i, to=to_i)
            except Exception: pass
        # input ar/ac if present (treated as decode-side conversion, rare)
        work_audios.append(work)
    if not outputs:
        if inputs:
            ST.print_banner(); ST.error("At least one output file must be specified\n"); return 1
        # outputs but no inputs handled below
    if inputs and not outputs:
        ST.print_banner(); ST.error("At least one output file must be specified\n"); return 1
    # Pre-validate outputs
    contexts=[]
    for oi, spec in enumerate(outputs):
        url=spec.url; opts=spec.opts
        fmt, forced = format_for_output(url, opts)
        ctx=OutputContext(); ctx.index=oi; ctx.url=url; ctx.out_opts=opts; ctx.fmt=fmt
        ctx.out_addr=ST.addr(); ctx.addr_map={}
        # pick source
        src_idx=0
        maps=get_opts_all(opts, ['map'])
        if maps:
            m=re.match(r'\s*(\d+)', str(maps[0]))
            if m:
                try:
                    cand=int(m.group(1))
                    if 0 <= cand < len(audios): src_idx=cand
                except Exception: pass
        ctx.source_index=src_idx
        ctx.source_orig=audios[src_idx] if audios else None
        ctx.source_work=work_audios[src_idx] if audios else None
        ctx.sample_altered=False
        # detect sample-altering options for copy mode
        altering=['ss','t','to','ar','ac','af','filter:a','filter','vf','vol','sample_fmt']
        # input-side alteration already in work: compare frames
        if ctx.source_work is not None and ctx.source_orig is not None:
            if ctx.source_work.frames()!=ctx.source_orig.frames() or ctx.source_work.rate!=ctx.source_orig.rate:
                ctx.sample_altered=True
        for k,v in opts.items:
            if k in altering or k.startswith('af') or k.startswith('filter'):
                ctx.sample_altered=True
        if fmt is None or (forced and fmt not in get_muxer_names() and fmt not in DEFAULT_CODEC_FOR_FORMAT and fmt not in RAW_FORMAT_TO_CODEC):
            ST.print_banner()
            if forced:
                ST.error("[AVFormatContext @ %s] Requested output format '%s' is not known.\n" % (ST.addr(), fmt))
            else:
                ST.error("[AVFormatContext @ %s] Unable to choose an output format for '%s'; use a standard extension for the filename or specify the format manually.\n" % (ST.addr(), display_url(url)))
            ST.error("[out#%d @ %s] Error initializing the muxer for %s: Invalid argument\n" % (oi, ctx.out_addr, display_url(url) if forced==False else url))
            eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % url)
            return 234
        ctx.fmt=fmt
        # no inputs -> no stream
        if not audios:
            ST.info("Output #%d, %s, to '%s':\n" % (oi, fmt, display_url(url)))
            ST.error("[out#%d/%s @ %s] Output file does not contain any stream\n" % (oi, fmt, ctx.out_addr))
            eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % url)
            return 234
        # -an
        if opts.has(['an']) or get_opt(opts, ['c:a'])=='disable':
            ST.info("Output #%d, %s, to '%s':\n" % (oi, fmt, display_url(url)))
            ST.error("[out#%d/%s @ %s] Output file does not contain any stream\n" % (oi, fmt, ctx.out_addr))
            eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % url)
            return 234
        # determine codec
        codec_req=get_opt(opts, ['c:a','codec:a','c','codec','acodec'])
        # generic -c also stored as 'c'
        if codec_req is None:
            codec_req=get_opt(opts, ['c'])
        copy_mode=False
        if codec_req=='copy':
            copy_mode=True; codec=ctx.source_orig.codec
        elif codec_req:
            codec=codec_req
            if codec not in get_encoder_names():
                ST.print_banner()
                aost_addr=ST.addr()
                ST.error("[aost#%d:0 @ %s] Unknown encoder '%s'\n" % (oi, aost_addr, codec))
                ST.error("[aost#%d:0 @ %s] Error selecting an encoder\n" % (oi, aost_addr))
                eprint_msg("Error opening output file %s.\nError opening output files: Encoder not found\n" % url)
                return 8
        else:
            codec=DEFAULT_CODEC_FOR_FORMAT.get(fmt)
            if codec is None:
                codec='pcm_s16le'
            if codec not in get_encoder_names():
                ST.print_banner(); aost_addr=ST.addr()
                ST.error("[aost#%d:0 @ %s] Automatic encoder selection failed Default encoder for format %s (codec %s) is probably disabled. Please choose an encoder manually.\n" % (oi, aost_addr, fmt, codec))
                ST.error("[aost#%d:0 @ %s] Error selecting an encoder\n" % (oi, aost_addr))
                eprint_msg("Error opening output file %s.\nError opening output files: Encoder not found\n" % url)
                return 8
        ctx.codec=codec; ctx.copy_mode=copy_mode
        # metadata syntax
        for k,v in opts.items:
            if (k=='metadata' or k.startswith('metadata:')) and '=' not in v:
                ST.print_banner()
                ST.error("[out#%d/%s @ %s] No '=' character in metadata string %s.\n" % (oi, fmt, ctx.out_addr, v))
                eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % url)
                return 234
        # filter validation will happen during processing; validate names early similarly
        # overwrite / file access
        if url not in ('-','pipe:','pipe:1','pipe:2') and not '://' in url:
            path=url[7:] if url.startswith('file://') else url
            if os.path.isdir(path):
                ST.print_banner()
                ST.error("[out#%d/%s @ %s] Error opening output %s: Is a directory\n" % (oi, fmt, ctx.out_addr, url))
                eprint_msg("Error opening output file %s.\nError opening output files: Is a directory\n" % url); return 235
            parent=os.path.dirname(os.path.abspath(path))
            if not os.path.isdir(parent):
                ST.print_banner()
                ST.error("[out#%d/%s @ %s] Error opening output %s: No such file or directory\n" % (oi, fmt, ctx.out_addr, url))
                eprint_msg("Error opening output file %s.\nError opening output files: No such file or directory\n" % url); return 254
            if os.path.exists(path):
                if ST.overwrite is False:
                    ST.print_banner()
                    ST.error("File '%s' already exists. Exiting.\n" % url)
                    eprint_msg("Error opening output file %s.\n" % url)
                    return 0
                if ST.overwrite is None:
                    ST.print_banner()
                    # prompt (stderr, no newline)
                    if ST.loglevel>=32:
                        sys.stderr.write("File '%s' already exists. Overwrite? [y/N] " % url); sys.stderr.flush()
                    ans=''
                    try:
                        b=sys.stdin.buffer.read(1)
                        ans=b.decode('utf-8','ignore') if b else ''
                        # consume rest of line if present and stdin is not a tty? ffmpeg reads a line-ish; reading 1 byte leaves newline for possible next prompt - to mimic, consume until newline if available and data is pipe
                        # do not block: only if stdin is not tty, try to drain line in non? skip
                    except Exception:
                        ans=''
                    if ans not in ('y','Y'):
                        if ST.loglevel>=32:
                            sys.stderr.write("Not overwriting - exiting\n")
                        eprint_msg("Error opening output file %s.\n" % url)
                        return 0
        contexts.append(ctx)
    # stream mapping
    ST.info("Stream mapping:\n")
    for ctx in contexts:
        src=ctx.source_orig
        if ctx.copy_mode:
            ST.info("  Stream #%d:0 -> #%d:0 (copy)\n" % (ctx.source_index, ctx.index))
        else:
            ST.info("  Stream #%d:0 -> #%d:0 (%s (native) -> %s (native))\n" % (ctx.source_index, ctx.index, src.codec, ctx.codec))
    if not ST.nostdin:
        ST.info("Press [q] to stop, [?] for help\n")
    ST.start_time=time.time()
    stats_list=[]
    for ctx in contexts:
        # special copy-to-flac incompatibility (prints after mapping, no Output header)
        if ctx.copy_mode and ctx.fmt=='flac' and ctx.source_orig.codec!='flac':
            flac_addr=ST.addr()
            ST.error("[flac @ %s] Invalid audio stream. Exactly one FLAC audio stream is required.\n" % flac_addr)
            ST.error("[out#%d/flac @ %s] Could not write header (incorrect codec parameters ?): Invalid argument\n" % (ctx.index, ctx.out_addr))
            ST.error("Conversion failed!\n")
            # create/truncate output like ffmpeg (it already opened file)
            if ctx.url not in ('-','pipe:','pipe:1'):
                try: open(ctx.url,'wb').close()
                except Exception: pass
            return 234
        ctx.output_metadata=prepare_metadata(ctx.source_orig, ctx.out_opts, ctx.fmt)
        # process (may raise filter errors etc)
        try:
            stats=process_and_encode(ctx)
        except FFError as e:
            if e.kind=='filter_notfound':
                ST.print_banner()
                ST.error("[AVFilterGraph @ %s] No such filter: '%s'\n" % (ST.addr(), e.msg))
                eprint_msg("Error opening output file %s.\nError opening output files: Filter not found\n" % ctx.url); return 8
            if e.kind=='invalidarg_filter_parse':
                ST.print_banner()
                av_addr=ST.addr()
                # token is in e.msg
                tok=e.msg
                argpart=tok.split('=',1)[1] if '=' in tok else ''
                ST.error("[AVFilterGraph @ %s] No option name near '%s'\n" % (av_addr, argpart))
                ST.error("[AVFilterGraph @ %s] Error parsing a filter description around: \n" % av_addr)
                ST.error("[AVFilterGraph @ %s] Error parsing filterchain '%s' around: \n" % (av_addr, tok))
                eprint_msg("Error opening output file %s.\nError opening output files: Invalid argument\n" % ctx.url); return 234
            if e.kind=='invalidarg_volume':
                ST.print_banner()
                parsed_addr=ST.addr()
